internal object uniffiCallbackInterfaceKeychain {
    internal object `get`: UniffiCallbackInterfaceKeychainMethod0 {
        override fun callback(`uniffiHandle`: Long,`item`: RustBuffer.ByValue,`uniffiOutReturn`: RustBuffer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeKeychain.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`get`(
                    FfiConverterString.lift(`item`),
                )
            }
            val writeReturn = { value: kotlin.ByteArray? -> uniffiOutReturn.setValue(FfiConverterOptionalByteArray.lower(value)) }
            uniffiTraitInterfaceCallWithError(
                uniffiCallStatus,
                makeCall,
                writeReturn,
                { e: BaudException -> FfiConverterTypeBaudError.lower(e) }
            )
        }
    }
    internal object `put`: UniffiCallbackInterfaceKeychainMethod1 {
        override fun callback(`uniffiHandle`: Long,`item`: RustBuffer.ByValue,`bytes`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeKeychain.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`put`(
                    FfiConverterString.lift(`item`),
                    FfiConverterByteArray.lift(`bytes`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCallWithError(
                uniffiCallStatus,
                makeCall,
                writeReturn,
                { e: BaudException -> FfiConverterTypeBaudError.lower(e) }
            )
        }
    }
    internal object `delete`: UniffiCallbackInterfaceKeychainMethod2 {
        override fun callback(`uniffiHandle`: Long,`item`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeKeychain.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`delete`(
                    FfiConverterString.lift(`item`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCallWithError(
                uniffiCallStatus,
                makeCall,
                writeReturn,
                { e: BaudException -> FfiConverterTypeBaudError.lower(e) }
            )
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeKeychain.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeKeychain.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceKeychain.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `get`,
        `put`,
        `delete`,
    )

