 * One case per thing the UI says differently; the message is the sentence to show.
 */
sealed class BaudException(message: String): kotlin.Exception(message) {
        
        class NotFound(message: String) : BaudException(message)
        
        class Expired(message: String) : BaudException(message)
        
        class Used(message: String) : BaudException(message)
        
        class BadLink(message: String) : BaudException(message)
        
        class NotAdmin(message: String) : BaudException(message)
        
        class NotMember(message: String) : BaudException(message)
        
    /**
     * The other side said no (their gate closed, or my other device declined the link).
     */
        class Refused(message: String) : BaudException(message)
        
        class Offline(message: String) : BaudException(message)
        
        class Unreachable(message: String) : BaudException(message)
        
        class Store(message: String) : BaudException(message)
        
        class Failed(message: String) : BaudException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BaudException> {
        override fun lift(error_buf: RustBuffer.ByValue): BaudException = FfiConverterTypeBaudError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeBaudError : FfiConverterRustBuffer<BaudException> {
    override fun read(buf: ByteBuffer): BaudException {
        
            return when(buf.getInt()) {
            1 -> BaudException.NotFound(FfiConverterString.read(buf))
            2 -> BaudException.Expired(FfiConverterString.read(buf))
            3 -> BaudException.Used(FfiConverterString.read(buf))
            4 -> BaudException.BadLink(FfiConverterString.read(buf))
            5 -> BaudException.NotAdmin(FfiConverterString.read(buf))
            6 -> BaudException.NotMember(FfiConverterString.read(buf))
            7 -> BaudException.Refused(FfiConverterString.read(buf))
            8 -> BaudException.Offline(FfiConverterString.read(buf))
            9 -> BaudException.Unreachable(FfiConverterString.read(buf))
            10 -> BaudException.Store(FfiConverterString.read(buf))
            11 -> BaudException.Failed(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: BaudException): ULong {
        return 4UL
    }

    override fun write(value: BaudException, buf: ByteBuffer) {
        when(value) {
            is BaudException.NotFound -> {
