                Unit
            }
            is BaudException.Expired -> {
                buf.putInt(2)
                Unit
            }
            is BaudException.Used -> {
                buf.putInt(3)
                Unit
            }
            is BaudException.BadLink -> {
                buf.putInt(4)
                Unit
            }
            is BaudException.NotAdmin -> {
                buf.putInt(5)
                Unit
            }
            is BaudException.NotMember -> {
                buf.putInt(6)
                Unit
            }
            is BaudException.Refused -> {
                buf.putInt(7)
                Unit
            }
            is BaudException.Offline -> {
                buf.putInt(8)
                Unit
            }
            is BaudException.Unreachable -> {
                buf.putInt(9)
                Unit
            }
            is BaudException.Store -> {
                buf.putInt(10)
                Unit
            }
            is BaudException.Failed -> {
                buf.putInt(11)
